@php
    $event = $event ?? null;
    $selectedRoles = old('roles', $event?->roleRequirements?->map(fn($requirement) => $requirement->crewRole->code)->all() ?? []);
    $dayRows = old('days');
    if ($dayRows === null) {
        $dayRows = $event?->shifts?->groupBy(fn($shift) => $shift->shift_date?->toDateString())->map(function ($shifts, $date) {
            $morning = $shifts->first(fn($shift) => $shift->period->value === 'morning');
            $afternoon = $shifts->first(fn($shift) => $shift->period->value === 'afternoon');
            return [
                'date' => $date,
                'morning' => (bool) $morning,
                'afternoon' => (bool) $afternoon,
                'morning_uuid' => $morning?->uuid,
                'afternoon_uuid' => $afternoon?->uuid,
                'setup_period' => $morning?->requires_setup ? 'morning' : ($afternoon?->requires_setup ? 'afternoon' : ''),
                'set_down_period' => $morning?->requires_set_down ? 'morning' : ($afternoon?->requires_set_down ? 'afternoon' : ''),
            ];
        })->values()->all() ?? [[]];
    }
