@push('scripts')<script nonce="{{ request()->attributes->get('csp_nonce') }}">(()=>{const contact=document.getElementById('competition-contact');contact.addEventListener('change',()=>{const option=contact.selectedOptions[0];if(!option?.value)return;document.getElementById('competition-name').value=option.dataset.name;document.getElementById('organiser-name').value=option.dataset.organiser;document.getElementById('organiser-email').value=option.dataset.email;document.getElementById('organiser-phone').value=option.dataset.phone;});const rows=document.getElementById('day-rows');const template=document.getElementById('day-template');let next={{ count($dayRows) }};function number(){rows.querySelectorAll('.day-number').forEach((node,index)=>node.textContent=index+1)}document.getElementById('add-day').addEventListener('click',()=>{rows.insertAdjacentHTML('beforeend',template.innerHTML.replaceAll('__INDEX__',next++));number()});rows.addEventListener('click',event=>{if(event.target.classList.contains('remove-day')&&rows.querySelectorAll('.day-row').length>1){event.target.closest('.day-row').remove();number()}})})();</script>@endpush
